import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"解","description":"东坡易传 - 解","frontmatter":{"title":"解","description":"东坡易传 - 解"},"headers":[],"relativePath":"zh/classics/dongpo/041.md","filePath":"zh/classics/dongpo/041.md"}'),o={name:"zh/classics/dongpo/041.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><p>“解”：利西南。無所往，其來複，吉。有攸往，夙吉。</p><p>《彖》曰：“解”，險以動，動而免乎險，解。“解，利西南”，往得衆也；“其來複，吉”，乃得中也。“有攸往，夙吉”，往有功也。天地“解”而雷雨作，雷雨作而百果草木皆甲圻。“解”之時大矣哉！</p><p>所以爲“解”者，“震”也，“坎”也。“震”，東也；“坎”，北也。“解”者在此，所“解”在彼。東北，“解”者之所在；則西南，所“解”之地也。在難而思“解”，處安而惡擾者，物之情也。方其在難，我往則得衆，故“利西南”；及其無難，我往則害物，故“來複，吉”。“復”者，復東北也。東北有時而當復，是以不言其不利也。“來複”之爲“吉”者，夙所往之時也①，苟“有攸往”，非夙不可。“有攸往”而不夙，難深而不可“解”矣。</p><p>【校注】 ① 夙所往：《蘇氏易傳》作“九所住”，誤。</p><p>象曰：雷雨作，“解”。君子以赦過宥罪。</p><p>初六：無咎。象曰：剛柔之際，義“無咎”也。</p><p>“解”有二陽：九二有應於六五，而九四有應於初六，各得其正，而分定矣。惟六三者，無應而處於二陽之間，兼與二陽而“解”，始有爭矣。故“解”之所疾者，莫如六三也。六三欲以其不正亂人之正，故初與五皆其所疑而咎之。以其疑而咎之也，故特明其“無咎”，曰此與九四剛柔之際也，於義無咎。</p><p>九二：田獲三狐，得黃矢，貞吉。象曰：九二“貞吉”，得中道也。</p><p>九二之所當得者，六五也。近而可取者，初六、六三也。此之謂“三狐”。三狐皆可取，而以得六五爲“貞吉”也。此之謂“黃矢”，“黃”，中也；“矢”，直也。直其所當得也，是以六五爲“黃矢”；釋其所不當得之三狐，而取其所當得之一矢，息爭之道也。</p><p>六三：負且乘，致寇至，貞吝。象曰：“負且乘”，亦可醜也；自我致戎，又誰咎也？</p><p>三於四爲“負”，於二爲“乘”。乘而不負，若負而不乘，猶可以免於寇。寇之所伐者，負且乘也。夫三苟與四而不與二，則四不伐；與二而不與四，則二不攻。所以致寇者，由兼與也。二與四皆非其配，雖貞於一猶吝也，而況兼與乎？醜之甚也！</p><p>九四：解而拇，朋至斯孚。象曰：“解而拇”，未當位也。</p><p>“拇”，六三；“朋”九二也。三來附己①，解而不取，則二信之。“未當位”者，明勢不可以爭也。</p><p>【校注】 ① 附己：《蘇氏易傳》作“附已”，誤。</p><p>六五：君子維有解，吉；有孚於小人。象曰：君子有“解”，小人退也。</p><p>六五，九二之配也。而近於四，六三欲附於二與四，故疑而疾之。夫以六五之中直，豈與六三爭所附者哉？而六三以小人之意，度君子之心，故六五“維有解，吉”。“維有解”者，無所不解之謂也。近則解四，遠則解二，是以六三釋然而退也。</p><p>上六：公用射隼於高墉之上，獲之，無不利。象曰：“公用射隼”，以解悖也。</p><p>“隼”者，六三也；“墉”者，二陽之間也；“悖”者，爭也。二陽之所以爭而不已者，以六三之不去也。孰能去之？將使二與四乎？二與四固欲得之，將使初與五乎？則初與五，二陽之配，三之所疑也。夫欲弊所爭而解交鬥，惟不涉其黨者能之，故“高墉”之“隼”，惟上六爲能射而獲也。隼獲爭解，二與四無不利者。</p>',19)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
